// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        Reverter reverter = new Reverter();
        address actor = address(0x1234);
        vm.prank(actor);
        bool success;
        try c.forward(address(reverter), _data) { success = true; } catch { success = false; }
        assertTrue(!success, "Should revert when callee fails");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
